#nullable enable // autogenerated

using MVZ2.Vanilla;
using MVZ2Logic.Difficulties;
using PVZEngine;

namespace MVZ2.GameContent.Difficulties
{
    public static class VanillaDifficulties
    {
        public static readonly NamespaceID easy = LogicDifficultyID.easy;
        public static readonly NamespaceID normal = LogicDifficultyID.normal;
        public static readonly NamespaceID hard = LogicDifficultyID.hard;
        public static readonly NamespaceID lunatic = LogicDifficultyID.lunatic;
        public static NamespaceID Get(string name)
        {
            return new NamespaceID(VanillaMod.spaceName, name);
        }
    }
}
